#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MOD = 1000000007;

int add(int a, int b) {
    a += b;
    return a >= MOD ? a - MOD : a;
}

int sub(int a, int b) {
    return a >= b ? a - b : a + MOD - b;
}

long long mul(long long a, long long b) {
    return (a * b) % MOD;
}

int modPow(int base, int exp) {
    int res = 1;
    while (exp) {
        if (exp & 1) res = mul(res, base);
        base = mul(base, base);
        exp >>= 1;
    }
    return res;
}

int n;
int prob[8][8];
int match[8][8];
int tripleIdx[7][7][7];
int fullMask;
int dp[1048576];
int result;

bool check(int x, int y, int z) {
    int vals[4] = {0, x, y, z};
    int idx[4] = {0, 1, 2, 3};
    do {
        bool ok = true;
        for (int i = 1; i <= 3; ++i) {
            if (!match[idx[i]][vals[i]]) {
                ok = false;
                break;
            }
        }
        if (ok) return true;
    } while (next_permutation(idx + 1, idx + 4));
    return false;
}

void dfs1(int cur, int r, int c) {
    if (!cur) return;
    if (r == 4) {
        bool used[7] = {false, true, true, true, true, true, true};
        int state = 0;
        for (int i = 1; i <= 6; ++i) {
            for (int j = i + 1; j <= 6; ++j) {
                for (int k = j + 1; k <= 6; ++k) {
                    if (check(i, j, k)) {
                        used[i] = used[j] = used[k] = false;
                        int a = -1, b = -1, c = -1;
                        for (int l = 1; l <= 6; ++l) {
                            if (!used[l]) {
                                if (a == -1) a = l;
                                else if (b == -1) b = l;
                                else c = l;
                            }
                        }
                        used[i] = used[j] = used[k] = true;
                        if (c != -1) state |= tripleIdx[a][b][c];
                    }
                }
            }
        }
        dp[state] = add(dp[state], cur);
        return;
    }
    match[r][c] = 1;
    int nextVal = mul(cur, prob[r][c]);
    if (c == 6) dfs1(nextVal, r + 1, 1);
    else dfs1(nextVal, r, c + 1);
    match[r][c] = 0;
    nextVal = mul(cur, sub(1, prob[r][c]));
    if (c == 6) dfs1(nextVal, r + 1, 1);
    else dfs1(nextVal, r, c + 1);
}

void dfs2(int cur, int r, int c) {
    if (!cur) return;
    if (r == 7) {
        int state = 0;
        for (int i = 1; i <= 6; ++i) {
            for (int j = i + 1; j <= 6; ++j) {
                for (int k = j + 1; k <= 6; ++k) {
                    if (check(i, j, k)) state |= tripleIdx[i][j][k];
                }
            }
        }
        result = add(result, mul(cur, dp[fullMask ^ state]));
        return;
    }
    match[r - 3][c] = 1;
    int nextVal = mul(cur, prob[r][c]);
    if (c == 6) dfs2(nextVal, r + 1, 1);
    else dfs2(nextVal, r, c + 1);
    match[r - 3][c] = 0;
    nextVal = mul(cur, sub(1, prob[r][c]));
    if (c == 6) dfs2(nextVal, r + 1, 1);
    else dfs2(nextVal, r, c + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    int inv100 = modPow(100, MOD - 2);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            int x; cin >> x;
            prob[i][j] = mul(x, inv100);
        }
    }
    for (int i = n + 1; i <= 6; ++i) prob[i][i] = 1;
    int cnt = 0;
    for (int i = 1; i <= 6; ++i) {
        for (int j = i + 1; j <= 6; ++j) {
            for (int k = j + 1; k <= 6; ++k) {
                tripleIdx[i][j][k] = 1 << cnt;
                ++cnt;
            }
        }
    }
    fullMask = (1 << cnt) - 1;
    dfs1(1, 1, 1);
    int totalStates = 1 << cnt;
    for (int bit = 0; bit < cnt; ++bit) {
        for (int mask = 0; mask < totalStates; ++mask) {
            if (mask & (1 << bit)) {
                dp[mask] = add(dp[mask], dp[mask ^ (1 << bit)]);
            }
        }
    }
    result = 0;
    dfs2(1, 4, 1);
    result = sub(1, result);
    cout << result << '\n';
    return 0;
}
